#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    vector<long long> inputs(2);
    for (int i = 0; i < 2; ++i) {
        cin >> inputs[i];
    }
    n = inputs[0];
    k = inputs[1];

    vector<bool> visited(n + 1, false);
    vector<int> adj_list(n + 1, -1);

    for (int index = 0; index < n; ++index) {
        adj_list[index] = (index * k) % n;
    }

    function<void(int)> explore = [&](int current) {
        visited[current] = true;
        while (!visited[adj_list[current]]) {
            current = adj_list[current];
            visited[current] = true;
        }
    };

    const long long MOD = 1000000007;
    int component_count = 0;

    for (int start = 1; start < n; ++start) {
        if (!visited[start]) {
            explore(start);
            component_count++;
        }
    }

    if (k == 1) {
        long long result = 1;
        for (int i = 0; i < n; ++i) {
            result = (result * n) % MOD;
        }
        cout << result << "\n";
    } else {
        long long result = 1;
        for (int i = 0; i < component_count; ++i) {
            result = (result * n) % MOD;
        }
        cout << result << "\n";
    }

    return 0;
}
